        id: this.nextId(),
        email
      };
      await admin.create(newAdmin);
    } catch (error) {
      throw new Error('Failed to create admin');
    }
  }

  // Update an admin by ID
  async update(id) {
    try {
      const { email } = body();
      if (!email) {
        throw new Error('Email is required');
